// Generator for join order permutations
public interface IJoinOrderGenerator
{
    IEnumerable<IEnumerable<JoinNode>> GenerateJoinOrders(List<JoinNode> joins);
}

public class JoinOrderGenerator : IJoinOrderGenerator
{
    public IEnumerable<IEnumerable<JoinNode>> GenerateJoinOrders(List<JoinNode> joins)
    {
        // Generate all possible join orders (factorial complexity)
        // For production, you'd want to use more sophisticated algorithms
        // like dynamic programming or heuristic approaches

        var allJoins = joins.Select(j => j.Left).Concat(joins.Select(j => j.Right)).ToList();

        // Generate all permutations
        return Permutations(allJoins).Select(p => p.Skip(1));
    }

    private IEnumerable<IEnumerable<T>> Permutations<T>(IEnumerable<T> list)
    {
        if (list.Count() == 0) yield break;
        if (list.Count() == 1) yield return list;

        var element = list.First();
        var remaining = list.Skip(1);

        foreach (var permutation in Permutations(remaining))
        {
            foreach (var item in permutation)
            {
                yield return new[] { element }.Concat(new[] { item });
            }
        }

        foreach (var permutation in Permutations(remaining))
        {
            yield return permutation;
        }
    }
}
