## 3. Execution Plan Generator

```csharp
public enum PhysicalOperatorType
{
    Scan,
    Filter,
    Project,
    Join,
    Aggregate,
    Sort,
    Distribute,
    Gather
}

public class PhysicalOperator
{
    public PhysicalOperatorType Type { get; set; }
    public Dictionary<string, object> Properties { get; } = new Dictionary<string, object>();
    public List<PhysicalOperator> Children { get; } = new List<PhysicalOperator>();
}

public class ExecutionPlanGenerator
{
    private readonly IStatisticsProvider _statisticsProvider;

    public ExecutionPlanGenerator(IStatisticsProvider statisticsProvider)
    {
        _statisticsProvider = statisticsProvider;
    }

    public PhysicalOperator GeneratePlan(SqlNode query)
    {
        return GeneratePlanRecursive(query);
    }

    private PhysicalOperator GeneratePlanRecursive(SqlNode sqlNode)
    {
        switch (sqlNode)
        {
            case SelectNode select:
                return GenerateSelectPlan(select);
            case JoinNode join:
                return GenerateJoinPlan(join);
            // Add other cases for other node types
            default:
                throw new NotImplementedException($"Unsupported node type: {sqlNode.GetType()}");
        }
    }

    private PhysicalOperator GenerateSelectPlan(SelectNode select)
    {
        // First generate the FROM clause (which may contain joins)
        var fromPlan = GeneratePlanRecursive(select.FromClause);

        // Then add WHERE filters
        var wherePlan = new PhysicalOperator { Type = PhysicalOperatorType.Filter };
        wherePlan.Properties["condition"] = select.WhereClause;
        wherePlan.Children.Add(fromPlan);

        // Then add SELECT projection
        var projectPlan = new PhysicalOperator { Type = PhysicalOperatorType.Project };
        projectPlan.Properties["columns"] = select.SelectList;
        projectPlan.Children.Add(wherePlan);

        // Add GROUP BY if present
        if (select.GroupByClause != null && select.GroupByClause.Any())
        {
            var groupByPlan = new PhysicalOperator { Type = PhysicalOperatorType.Aggregate };
            groupByPlan.Properties["groupBy"] = select.GroupByClause;
            groupByPlan.Children.Add(projectPlan);
            projectPlan = groupByPlan;
        }

        // Add ORDER BY if present
        if (select.OrderByClause != null && select.OrderByClause.Any())
        {
            var sortPlan = new PhysicalOperator { Type = PhysicalOperatorType.Sort };
            sortPlan.Properties["orderBy"] = select.OrderByClause;
            sortPlan.Children.Add(projectPlan);
            projectPlan = sortPlan;
        }

        return projectPlan;
    }

    private PhysicalOperator GenerateJoinPlan(JoinNode join)
    {
        // Generate plans for left and right sides
        var leftPlan = GeneratePlanRecursive(join.Left);
        var rightPlan = GeneratePlanRecursive(join.Right);

        // Create join operator
        var joinPlan = new PhysicalOperator { Type = PhysicalOperatorType.Join };
        joinPlan.Properties["joinType"] = join.JoinType;
        joinPlan.Properties["condition"] = join.JoinConditions;
        joinPlan.Children.Add(leftPlan);
        joinPlan.Children.Add(rightPlan);

        return joinPlan;
    }

