## Integration and Usage Example

```csharp
public class DistributedQueryOptimizer
{
    private readonly SqlParser _parser;
    private readonly CostBasedOptimizer _optimizer;
    private readonly ExecutionPlanGenerator _planGenerator;

    public DistributedQueryOptimizer()
    {
        // Initialize components with their dependencies
        var statisticsProvider = new InMemoryStatisticsProvider(); // Implement this
        _parser = new SqlParser();
        _optimizer = new CostBasedOptimizer(statisticsProvider, new JoinOrderGenerator());
        _planGenerator = new ExecutionPlanGenerator(statisticsProvider);
    }

    public PhysicalOperator OptimizeAndPlan(string sql)
    {
        // Parse the SQL into AST
        var ast = _parser.Parse(sql);

        // Optimize the AST
        var optimizedAst = _optimizer.Optimize(ast);

        // Generate execution plan
        return _planGenerator.GeneratePlan(optimizedAst);
    }
}

// Example usage
class Program
{
    static void Main(string[] args)
    {
        var optimizer = new DistributedQueryOptimizer();
        string query = "SELECT a.id, b.name FROM table1 a INNER JOIN table2 b ON a.id = b.id WHERE a.value > 100";

        var plan = optimizer.OptimizeAndPlan(query);

        // Print or use the execution plan
        PrintPlan(plan);
    }

    static void PrintPlan(PhysicalOperator plan, int indent = 0)
    {
        Console.WriteLine($"{new string(' ', indent)}{plan.Type}");
        foreach (var prop in plan.Properties)
        {
            Console.WriteLine($"{new string(' ', indent + 2)}{prop.Key}: {prop.Value}");
        }
        foreach (var child in plan.Children)
        {
            PrintPlan(child, indent + 2);
        }
    }
}
